import re

def node_by_title(doc, title):
    for node in doc["nodes"]:
        if node["title"] == title:
            return node
    return None

def children(doc, node):
    return [node_by_id(doc, cid) for cid in node.get("children", [])]

def node_by_id(doc, node_id):
    for node in doc["nodes"]:
        if node["node_id"] == node_id:
            return node
    return None

def scope_nodes(doc, scope):
    node = node_by_title(doc, scope)
    if not node:
        return []
    return children(doc, node)

def table_rows(node):
    if node["kind"] != "table":
        return []
    cols = node["table"]["columns"]
    return [(i, {cols[j]: row[j] for j in range(len(cols))}) 
            for i, row in enumerate(node["table"]["rows"])]

def entities(doc, scope) -> list:
    prod_node = node_by_title(doc, f"{scope}: Products")
    if not prod_node:
        return []

    entity_list = []
    for idx, row in table_rows(prod_node):
        pid = row["product"]
        desc = f"{pid} ({row['group']} {row['sub-group']})"
        entity_list.append({"id": pid, "description": desc})
    return entity_list

def recorded_end(doc, scope) -> float or None:
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if not ledger_node:
        return None

    max_day = 0
    for idx, row in table_rows(ledger_node):
        try:
            day = float(row["day"])
            if day > max_day:
                max_day = day
        except (ValueError, KeyError):
            continue
    return max_day if max_day > 0 else None

def inputs(doc, scope) -> list:
    inputs_list = []

    # Product attributes and opening stocks
    prod_node = node_by_title(doc, f"{scope}: Products")
    if prod_node:
        for idx, row in table_rows(prod_node):
            pid = row["product"]
            # Opening stock is an input at the start (assume time=1 for the period relative to the start)
            # But recorded_end is absolute day. Let's find the first day of the ledger.
            inputs_list.append({
                "id": f"opening_stock_{pid}",
                "time": None, # Will be clarified by ledger first day if needed, but usually start of period
                "kind": "opening_stock",
                "entities": [pid],
                "fields": {"opening_stock": float(row["opening stock"])},
                "src": [prod_node["node_id"], idx]
            })
            inputs_list.append({
                "id": f"weight_{pid}",
                "time": None,
                "kind": "product_weight",
                "entities": [pid],
                "fields": {"kg_per_unit": float(row["kg per unit"])},
                "src": [prod_node["node_id"], idx]
            })

    # Daily ledger production and orders
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for idx, row in table_rows(ledger_node):
            pid = row["product"]
            day = float(row["day"])
            # Production
            inputs_list.append({
                "id": f"prod_{day}_{pid}",
                "time": day,
                "kind": "production",
                "entities": [pid],
                "fields": {"produced": float(row["produced"])},
                "src": [ledger_node["node_id"], idx]
            })
            # Orders
            if float(row["ordered"]) > 0:
                inputs_list.append({
                    "id": f"order_{day}_{pid}",
                    "time": day,
                    "kind": "order",
                    "entities": [pid],
                    "fields": {"ordered": float(row["ordered"])},
                    "src": [ledger_node["node_id"], idx]
                })

    # Order book future inputs
    # Look for tables starting with "Plant #, Period #: Order book: Orders received and production planned"
    for node in doc["nodes"]:
        if node["title"].startswith(f"{scope}: Order book: Orders received and production planned"):
            for idx, row in table_rows(node):
                pid = row["product"]
                day = float(row["day"])
                inputs_list.append({
                    "id": f"plan_prod_{day}_{pid}",
                    "time": day,
                    "kind": "planned_production",
                    "entities": [pid],
                    "fields": {"planned_production": float(row["planned production"])},
                    "src": [node["node_id"], idx]
                })
                if float(row["ordered"]) > 0:
                    inputs_list.append({
                        "id": f"plan_order_{day}_{pid}",
                        "time": day,
                        "kind": "planned_order",
                        "entities": [pid],
                        "fields": {"ordered": float(row["ordered"])},
                        "src": [node["node_id"], idx]
                    })

    return inputs_list

def outcomes(doc, scope) -> list:
    outcomes_list = []

    # Daily ledger results
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for idx, row in table_rows(ledger_node):
            pid = row["product"]
            day = float(row["day"])
            outcomes_list.append({
                "time": day,
                "kind": "shipped",
                "entities": [pid],
                "value": float(row["shipped"]),
                "src": [ledger_node["node_id"], idx]
            })
            outcomes_list.append({
                "time": day,
                "kind": "backordered",
                "entities": [pid],
                "value": float(row["backordered"]),
                "src": [ledger_node["node_id"], idx]
            })
            outcomes_list.append({
                "time": day,
                "kind": "stock",
                "entities": [pid],
                "value": float(row["stock"]),
                "src": [ledger_node["node_id"], idx]
            })

    # Events
    event_node = node_by_title(doc, f"{scope}: Events")
    if event_node and event_node["kind"] == "list":
        for idx, line in enumerate(event_node["lines"]):
            # Format: "Day 29 (2023-01-29): ..."
            match = re.match(r"Day (\d+)", line)
            if match:
                day = float(match.group(1))
                # Extract product IDs from the line
                # Product IDs usually follow a pattern like POP001L12P-A
                p_ids = re.findall(r"([A-Z]{3}\d{3}[A-Z0-9-]+)", line)
                outcomes_list.append({
                    "time": day,
                    "kind": "event",
                    "entities": p_ids,
                    "value": None,
                    "src": [event_node["node_id"], idx]
                })

    return outcomes_list

def params(doc, scope) -> dict:
    params_dict = {}
    intro_node = node_by_title(doc, scope)
    if intro_node and intro_node["kind"] == "text":
        text = intro_node["text"]
        match = re.search(r"Daily dispatch capacity: (\d+)\s*kg", text)
        if match:
            params_dict["daily_dispatch_capacity"] = float(match.group(1))
    return params_dict

